export function applyN4KanjiPlan(units){for(const p of n4KanjiPlan){const u=units.find(u=>u.number===p.number);if(!u.words.some(w=>w.text===p.wordKey))u.words.push({...p.word,role:'Từ nền dùng lại cho chữ; lịch ôn chung'});const hex=[...p.wordKey].map(c=>c.codePointAt(0).toString(16)).join('-'),qid=u.questions.find(q=>q.wordKey===p.wordKey&&q.kind==='recall'&&q.assessment)?.id||'m'+p.number+'-r1-kanji-reading-'+hex;if(!u.questions.some(q=>q.id===qid))u.questions.push({id:qid,kind:'recall',assessment:true,prompt:'Đọc cả từ '+p.wordKey+' theo nghĩa “'+p.word.meaning+'”: gõ kana. Không chấm mọi âm riêng của chữ.',accepted:[p.word.reading],choices:[p.word.reading,'Chưa khớp'],answer:0,explanation:p.wordKey+' đọc '+p.word.reading+'. '+p.word.example.vi,skill:p.wordKey,wordKey:p.wordKey,usageId:'mnn-'+p.number+':'+p.wordKey});if(!u.kanji.some(k=>k.char===p.char))u.kanji.push({char:p.char,wordKey:p.wordKey,inWord:p.inWord,meaning:p.meaning,status:p.status,assessmentId:qid});}}
